//! Shared helpers for integration tests.

use std::path::PathBuf;

/// A golden fixture directory (`replies` or `control`) in `protocol/fixtures/`,
/// generated by the Swift implementation. `PLANMETER_FIXTURES=dir` forces
/// `dir/<sub>`.
pub fn fixture_dir(sub: &str) -> PathBuf {
    if let Some(dir) = std::env::var_os("PLANMETER_FIXTURES") {
        return PathBuf::from(dir).join(sub);
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../protocol/fixtures")
        .join(sub)
}

/// JSON files in a fixture subdirectory, sorted by name.
pub fn json_files(sub: &str) -> Vec<PathBuf> {
    let dir = fixture_dir(sub);
    let mut files: Vec<PathBuf> = std::fs::read_dir(&dir)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", dir.display()))
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.extension().is_some_and(|x| x == "json"))
        .collect();
    files.sort();
    files
}

pub fn stem(path: &std::path::Path) -> String {
    path.file_stem()
        .unwrap_or_default()
        .to_string_lossy()
        .into_owned()
}
